//! Differential test: compares `tpt-gis-geom` against GEOS (via shapely) on 400 random
//! polygon pairs, including touching, nested and holed cases. The reference values are in
//! `tests/fixtures/geos_pairs.csv`, generated by a script with the same seed.
//!
//! Predicate, area, centroid and hull checks run in every build. The clip-based checks
//! (intersection, union, difference areas) need the `alloc` feature.

use std::path::PathBuf;

#[cfg(feature = "alloc")]
use tpt_gis_geom::clip;
use tpt_gis_geom::convex_hull;
use tpt_gis_geom::predicates::{polygon_contains_polygon, polygons_intersect};
#[cfg(feature = "alloc")]
use tpt_gis_geom::relate::{polygons_overlap, polygons_touch};
use tpt_gis_geom::{Point, Polygon};

/// One row of the fixture, with its polygons parsed into owned rings. Some fields are only
/// read with the `alloc` feature.
#[allow(dead_code)]
struct Case {
    line: usize,
    a_rings: Vec<Vec<Point>>,
    b_rings: Vec<Vec<Point>>,
    area_a: f64,
    area_b: f64,
    hull_area_a: f64,
    centroid_a: (f64, f64),
    intersects: bool,
    covers: bool,
    touches: bool,
    overlaps: bool,
    intersection_area: f64,
    union_area: f64,
    difference_area: f64,
}

fn parse_rings(text: &str) -> Vec<Vec<Point>> {
    text.split('|')
        .map(|ring| {
            ring.split_whitespace()
                .map(|pair| {
                    let (x, y) = pair.split_once(',').unwrap();
                    Point::new(x.parse().unwrap(), y.parse().unwrap())
                })
                .collect()
        })
        .collect()
}

fn load_cases() -> Vec<Case> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/geos_pairs.csv");
    let text = std::fs::read_to_string(path).unwrap();
    text.lines()
        .enumerate()
        .filter(|(_, l)| !l.starts_with('#') && !l.trim().is_empty())
        .map(|(line, row)| {
            let f: Vec<&str> = row.split(';').collect();
            assert_eq!(f.len(), 14, "line {}", line + 1);
            let num = |i: usize| f[i].parse::<f64>().unwrap();
            let flag = |i: usize| f[i] == "1";
            Case {
                line: line + 1,
                a_rings: parse_rings(f[0]),
                b_rings: parse_rings(f[1]),
                area_a: num(2),
                area_b: num(3),
                hull_area_a: num(4),
                centroid_a: (num(5), num(6)),
                intersects: flag(7),
                covers: flag(8),
                touches: flag(9),
                overlaps: flag(10),
                intersection_area: num(11),
                union_area: num(12),
                difference_area: num(13),
            }
        })
        .collect()
}

/// Borrowed view of owned rings: exterior first, holes after.
fn as_polygon(rings: &[Vec<Point>]) -> (&[Point], Vec<&[Point]>) {
    let holes = rings[1..].iter().map(Vec::as_slice).collect();
    (rings[0].as_slice(), holes)
}

/// Relative-or-absolute agreement, with the scale set by the larger value.
fn close(got: f64, want: f64) -> bool {
    (got - want).abs() <= 1e-6 * want.abs().max(1.0)
}

#[test]
fn predicates_areas_and_hulls_agree_with_geos() {
    let cases = load_cases();
    assert!(cases.len() >= 300, "fixture has {} rows", cases.len());
    let mut mismatches = Vec::new();
    for c in &cases {
        let (ext_a, holes_a) = as_polygon(&c.a_rings);
        let (ext_b, holes_b) = as_polygon(&c.b_rings);
        let a = Polygon::new(ext_a, &holes_a);
        let b = Polygon::new(ext_b, &holes_b);
        let mut report = |what: &str, detail: String| {
            mismatches.push(format!("line {} {what}: {detail}", c.line));
        };

        if !close(a.area(), c.area_a) {
            report("area_a", format!("{} vs {}", a.area(), c.area_a));
        }
        if !close(b.area(), c.area_b) {
            report("area_b", format!("{} vs {}", b.area(), c.area_b));
        }
        if let Some(cen) = a.centroid() {
            if !close(cen.x, c.centroid_a.0) || !close(cen.y, c.centroid_a.1) {
                report("centroid_a", format!("({}, {})", cen.x, cen.y));
            }
        } else {
            report("centroid_a", "None".into());
        }

        let mut pts = ext_a.to_vec();
        let mut out = vec![Point::new(0.0, 0.0); 2 * pts.len()];
        let n = convex_hull(&mut pts, &mut out).unwrap();
        let hull = tpt_gis_geom::ring_signed_area(&out[..n]).abs();
        if !close(hull, c.hull_area_a) {
            report("hull_area_a", format!("{hull} vs {}", c.hull_area_a));
        }

        if polygons_intersect(&a, &b) != c.intersects {
            report("intersects", format!("ours {}", !c.intersects));
        }
        if polygon_contains_polygon(&a, &b) != c.covers {
            report("covers", format!("ours {}", !c.covers));
        }
        #[cfg(feature = "alloc")]
        if polygons_touch(&a, &b) != c.touches {
            report("touches", format!("ours {}", !c.touches));
        }
        #[cfg(feature = "alloc")]
        if polygons_overlap(&a, &b) != c.overlaps {
            report("overlaps", format!("ours {}", !c.overlaps));
        }

        #[cfg(feature = "alloc")]
        {
            let area_of =
                |parts: Vec<clip::OwnedPolygon>| parts.iter().map(|p| p.area()).sum::<f64>();
            let inter = area_of(clip::intersection(&a, &b));
            let uni = area_of(clip::union(&a, &b));
            let diff = area_of(clip::difference(&a, &b));
            if !close(inter, c.intersection_area) {
                report("intersection_area", format!("{inter} vs {}", c.intersection_area));
            }
            if !close(uni, c.union_area) {
                report("union_area", format!("{uni} vs {}", c.union_area));
            }
            if !close(diff, c.difference_area) {
                report("difference_area", format!("{diff} vs {}", c.difference_area));
            }
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} disagreements with GEOS out of {} pairs; first ones:\n{}",
        mismatches.len(),
        cases.len(),
        mismatches.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}
